module lawsuit_assignment (\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] R, S, L,\n    input [2:0] A_0, A_1, A_2, A_3, A_4, A_5, A_6, A_7,\n    input [2:0] B_0, B_1, B_2, B_3, B_4, B_5, B_6, B_7,\n    output reg [7:0] win,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] STATE_IDLE     = 3'd0;\n    localparam [2:0] STATE_RESET    = 3'd1;\n    localparam [2:0] STATE_PROCESS  = 3'd2;\n    localparam [2:0] STATE_FIND_MAX = 3'd3;\n    localparam [2:0] STATE_OUTPUT   = 3'd4;\n    \n    reg [2:0] state, next_state;\n    reg [7:0] mask;\n    reg [2:0] lawsuit_idx;\n    reg [2:0] current_min_max;\n    reg [7:0] best_mask;\n    \n    // Individual and corporate counters\n    reg [2:0] indv_cnt [0:7];\n    reg [2:0] corp_cnt [0:7];\n    \n    // Array assignments\n    reg [2:0] A_arr [0:7];\n    reg [2:0] B_arr [0:7];\n    \n    // Finding max\n    reg [2:0] max_win;\n    reg [3:0] max_idx;\n    \n    integer i;\n\n    // Combinational array assignments\n    always @* begin\n        A_arr[0] = A_0; A_arr[1] = A_1;\n        A_arr[2] = A_2; A_arr[3] = A_3;\n        A_arr[4] = A_4; A_arr[5] = A_5;\n        A_arr[6] = A_6; A_arr[7] = A_7;\n        \n        B_arr[0] = B_0; B_arr[1] = B_1;\n        B_arr[2] = B_2; B_arr[3] = B_3;\n        B_arr[4] = B_4; B_arr[5] = B_5;\n        B_arr[6] = B_6; B_arr[7] = B_7;\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= STATE_IDLE;\n            done <= 1'b0;\n            win <= 8'd0;\n            mask <= 8'd0;\n            lawsuit_idx <= 3'd0;\n            current_min_max <= 3'd7;\n            best_mask <= 8'd0;\n            max_win <= 3'd0;\n            max_idx <= 4'd0;\n            \n            // Reset counter arrays\n            for (i = 0; i < 8; i = i + 1) begin\n                indv_cnt[i] <= 3'd0;\n                corp_cnt[i] <= 3'd0;\n            end\n        end else begin\n            case (state)\n                STATE_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= STATE_RESET;\n                        mask <= 8'd0;\n                        current_min_max <= 3'd7;\n                        best_mask <= 8'd0;\n                    end\n                end\n                \n                STATE_RESET: begin\n                    // Reset counters\n                    for (i = 0; i < 8; i = i + 1) begin\n                        indv_cnt[i] <= 3'd0;\n                        corp_cnt[i] <= 3'd0;\n                    end\n                    lawsuit_idx <= 3'd0;\n                    state <= STATE_PROCESS;\n                    max_win <= 3'd0;  // Reset max for new mask\n                end\n                \n                STATE_PROCESS: begin\n                    if (lawsuit_idx < L) begin\n                        if (mask[lawsuit_idx]) begin\n                            // Corporation wins\n                            corp_cnt[B_arr[lawsuit_idx] - 3'd1] <= corp_cnt[B_arr[lawsuit_idx] - 3'd1] + 3'd1;\n                        end else begin\n                            // Individual wins\n                            indv_cnt[A_arr[lawsuit_idx] - 3'd1] <= indv_cnt[A_arr[lawsuit_idx] - 3'd1] + 3'd1;\n                        end\n                        lawsuit_idx <= lawsuit_idx + 3'd1;\n                    end else begin\n                        // Finished processing lawsuits for current mask\n                        state <= STATE_FIND_MAX;\n                        max_idx <= 4'd0;\n                    end\n                end\n                \n                STATE_FIND_MAX: begin\n                    if (max_idx < 4'd16) begin\n                        if (max_idx < 4'd8) begin\n                            // Individual counter\n                            if (indv_cnt[max_idx[2:0]] > max_win) begin\n                                max_win <= indv_cnt[max_idx[2:0]];\n                            end\n                        end else begin\n                            // Corporate counter\n                            if (corp_cnt[max_idx[2:0] - 3'd8] > max_win) begin\n                                max_win <= corp_cnt[max_idx[2:0] - 3'd8];\n                            end\n                        end\n                        max_idx <= max_idx + 4'd1;\n                    end else begin\n                        // Finished finding max for current mask\n                        if (max_win <= current_min_max) begin\n                            current_min_max <= max_win;\n                            best_mask <= mask;\n                        end\n                        \n                        if (mask == 8'd255) begin\n                            state <= STATE_OUTPUT;\n                        end else begin\n                            mask <= mask + 8'd1;\n                            state <= STATE_RESET;\n                        end\n                    end\n                end\n                \n                STATE_OUTPUT: begin\n                    win <= best_mask;\n                    done <= 1'b1;\n                    state <= STATE_IDLE;\n                end\n                \n                default: state <= STATE_IDLE;\n            endcase\n        end\n    end\n\nendmodule